import json
from pathlib import Path
p=Path('/app/benchmark/task_input.json')
data=json.loads(p.read_text())
print('top keys', data.keys())
print('site', data.get('site'))
for page in data.get('pages',[]):
    print('\nPAGE', page.get('slug') or page.get('id'), page.get('title'))
    for k,v in page.items():
        if k not in ('sections','content'):
            print(' ',k,':',v if not isinstance(v,(list,dict)) else type(v).__name__)
    for sec in page.get('sections',[]):
        print('  SEC', sec.get('id'), sec.get('title'), sec.get('type'))
        if sec.get('required_content'): print('   req', sec['required_content'][:5])
        if sec.get('interactions'): print('   interactions', sec['interactions'])
print('\nrequirements', data.get('requirements'))
print('\ninteractions')
for i in data.get('interactions',[]): print(i)
